// Build HMAC-signed S03 alert — fires on any unhandled A06 error.
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const e = $json;

let brand_id = null;
try { brand_id = $('Verify HMAC + parse').first().json.brand_id ?? null; } catch (_) {}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const makeUUID = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});

const body = JSON.stringify({
  anomaly_id:   makeUUID(),
  anomaly_type: 'extraction_failed',
  severity:     'error',
  source_flow:  'N8N-A06',
  brand_id,
  message:      e.execution?.error?.message || 'A06 extraction flow failed',
  details: {
    failed_node:  e.execution?.lastNodeExecuted ?? null,
    error_name:   e.execution?.error?.name      ?? null,
    execution_id: e.execution?.id               ?? null,
  },
  timestamp: new Date().toISOString(),
});

const sig = crypto.createHmac('sha256', SECRET).update(body).digest('hex');
return {
  _body: body,
  _headers: {
    'content-type':     'application/json',
    'x-n8n-signature':  sig,
    'x-n8n-request-id': `${$execution.id}-err-a06`,
    'x-n8n-timestamp':  new Date().toISOString(),
  },
};

// Verify HMAC + parse the inbound request from Next.js submitSeed.
// HARDCODED webhook secret + APP_BASE_URL for paste-and-run import. The
// downstream HTTP nodes use the same secret to sign their callbacks.
const WEBHOOK_SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';

const crypto = require('crypto');
const headers = $input.first().json.headers || {};
const given = headers['x-n8n-signature'];
const ts    = headers['x-n8n-timestamp'];
const rid   = headers['x-n8n-request-id'];
if (!given || !ts || !rid) throw new Error('Missing required HMAC headers');

const drift = Math.abs(Date.now() - Date.parse(ts));
if (drift > 5 * 60 * 1000) throw new Error(`Timestamp drift ${drift}ms > 5 min`);

const rawBody = JSON.stringify($input.first().json.body);
const expected = crypto.createHmac('sha256', WEBHOOK_SECRET).update(rawBody).digest('hex');
if (expected !== given) throw new Error('HMAC signature mismatch');

const body = $input.first().json.body || {};
if (!body.brand_id) throw new Error('brand_id required');

return { json: {
  brand_id: body.brand_id,
  slug: body.slug || null,
  instagram_handle: body.instagram_handle || null,
  website_url: body.website_url || null,
  place_search: body.place_search || { name: '', city: '' },
  request_id: rid,
}};

// Sign extraction_started stage callback.
const WEBHOOK_SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const APP_BASE_URL = 'https://vagrancy-pupil-spiritism.ngrok-free.dev';
const crypto = require('crypto');
const body = JSON.stringify({ brand_id: $json.brand_id, stage: 'extraction_started' });
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', WEBHOOK_SECRET).update(body).digest('hex');
return { json: { ...$json, _stage_url: APP_BASE_URL + '/api/processing/stage', _stage_body: body, _stage_headers: {
  'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts
}}};

// Sign the wrapper call to /api/extraction/run.
// This single endpoint runs all 3 scrapers in parallel via Promise.allSettled
// and returns the combined normalised payload — replaces the old
// 'Build jobs → Prep · IG/Web/Places → Apify HTTP nodes' chain.
const WEBHOOK_SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const APP_BASE_URL = 'https://vagrancy-pupil-spiritism.ngrok-free.dev';
const crypto = require('crypto');

const src = $('Verify HMAC + parse1').first().json;
const body = JSON.stringify({
  brand_id:         src.brand_id,
  slug:             src.slug || null,
  instagram_handle: src.instagram_handle || null,
  website_url:      src.website_url || null,
  place_search:     src.place_search || { name: '', city: '' },
});
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', WEBHOOK_SECRET).update(body).digest('hex');
return { json: { ...$json,
  _run_url: APP_BASE_URL + '/api/extraction/run',
  _run_body: body,
  _run_headers: {
    'content-type':'application/json',
    'x-n8n-signature':sig,
    'x-n8n-request-id':reqId,
    'x-n8n-timestamp':ts,
  },
}};

// Split the wrapper response into 3 ITEMS (one per branch). Each item
// carries:
//   • raw         — FULL untouched Apify / Places response (this is what
//                    we write to source_records.raw_payload — no field loss)
//   • normalised  — compact summary (used by UI for live extraction screen)
//   • persist_ig  — IG-only enrichment (post observations, signatures,
//                    channel profile, palette URLs, mentions, brand replies)
//
// Three items + sibling lanes via the Switch node = true parallel persistence.
const src = $('Verify HMAC + parse1').first().json;
const run = $json;
const result = run.body || run; // n8n responseFormat:'json' may wrap in body

const raw        = result.raw        || { instagram: null, website: null, places: null };
const normalised = result.normalised || { instagram: null, website: null, places: null };
const status     = result.status     || { instagram: 'skipped', website: 'skipped', places: 'skipped' };
const enrichment = result.enrichment || {};
const timing     = result.timing     || null;

// Optional log so the n8n execution view shows the wrapper's parallelism numbers
console.log('[A06] wrapper timing:', JSON.stringify({
  wall_ms: timing?.wall_time_ms,
  overlap_ms: timing?.parallel_overlap_ms,
  lanes: timing?.lanes,
}));

return [
  { json: {
    branch: 'instagram',
    brand_id: src.brand_id,
    skipped: status.instagram !== 'done',
    // FULL raw scraper output — written to source_records.raw_payload AS-IS.
    raw: raw.instagram,
    // Compact summary for the live UI / persist-ig signer.
    normalised: normalised.instagram,
    persist_ig: status.instagram === 'done' ? {
      ig_post_observations: enrichment.ig_post_observations || [],
      brand_reply_samples:  enrichment.brand_reply_samples  || [],
      signature_hashtags:   enrichment.signature_hashtags   || [],
      signature_phrases:    enrichment.signature_phrases    || [],
      // Enrich the channel_profile with the rich IG profile fields the
      // normaliser already produced (biography, full_name, profile_pic,
      // external_url, business_category, follows_count, joined_recently)
      // so persist-ig can write them all into channel_profiles (mig 0028).
      channel_profile: enrichment.channel_profile ? Object.assign({}, enrichment.channel_profile, {
        full_name:          normalised.instagram?.profile?.full_name          || null,
        biography:          normalised.instagram?.profile?.biography          || null,
        profile_pic_url:    normalised.instagram?.profile?.profile_pic_url    || null,
        external_url:       normalised.instagram?.profile?.external_url       || null,
        business_category:  normalised.instagram?.profile?.business_category  || null,
        follows_count:      normalised.instagram?.profile?.follows_count      || null,
        is_private:         !!normalised.instagram?.profile?.is_private,
        joined_recently:    !!normalised.instagram?.profile?.joined_recently,
        has_channel:        !!normalised.instagram?.profile?.has_channel,
        raw_profile:        raw.instagram?.details        || null,
        normalised_profile: normalised.instagram?.profile || null,
        posts_sample:       normalised.instagram?.posts_sample || null,
      }) : null,
      palette_image_urls:   enrichment.palette_image_urls   || [],
      mentions:             enrichment.mentions             || [],
    } : null,
  }},
  { json: {
    branch: 'website',
    brand_id: src.brand_id,
    skipped: status.website !== 'done',
    raw: raw.website,
    normalised: normalised.website,
  }},
  { json: {
    branch: 'places',
    brand_id: src.brand_id,
    skipped: status.places !== 'done',
    raw: raw.places,
    normalised: normalised.places,
  }},
];

// Sign /api/extraction/persist-source-record body for the IG branch.
// Migration 0028 splits the payload into explicit `raw` + `normalised`
// columns (queryable by the live status route + COO Pass 2). raw_payload
// is kept as the original blob for backward-compat / audit.
const WEBHOOK_SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const APP_BASE_URL = 'https://vagrancy-pupil-spiritism.ngrok-free.dev';
const crypto = require('crypto');
const typeMap = { instagram: 'instagram', website: 'website', places: 'google_places' };
const body = JSON.stringify({
  brand_id: $json.brand_id,
  source_type: typeMap[$json.branch] || $json.branch,
  branch: $json.branch,
  skipped: !!$json.skipped,
  raw: $json.raw,                // FULL Apify response (no field loss)
  normalised: $json.normalised,  // compact summary used by UI
  raw_payload: { branch: $json.branch, skipped: !!$json.skipped, raw: $json.raw, normalised: $json.normalised },
});
const ts = new Date().toISOString();
const reqId = crypto.randomUUID();
const sig = crypto.createHmac('sha256', WEBHOOK_SECRET).update(body).digest('hex');
return { json: { ...$json,
  _sr_url: APP_BASE_URL + '/api/extraction/persist-source-record',
  _sr_body: body,
  _sr_headers: { 'content-type':'application/json','x-n8n-signature':sig,'x-n8n-request-id':reqId,'x-n8n-timestamp':ts }
}};

